    private fun nativeLibrarySha256(context: Context, libraryFileName: String): String? {
        val nativeLibraryDir = context.applicationContext.applicationInfo.nativeLibraryDir
            ?.takeIf(String::isNotBlank)
            ?: return null
        val library = File(nativeLibraryDir, libraryFileName).takeIf(File::isFile) ?: return null
        return runCatching { library.sha256Hex() }.getOrNull()
    }

    private fun nativeLibrarySoFileName(libraryName: String): String = "lib$libraryName.so"

    private fun File.sha256Hex(): String {
        val digest = MessageDigest.getInstance("SHA-256")
        inputStream().use { input ->
            val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
            while (true) {
                val read = input.read(buffer)
                if (read < 0) {
                    break
                }
                digest.update(buffer, 0, read)
            }
        }
        return digest.digest().joinToString("") { "%02x".format(it) }
    }

    fun runEmbeddedScriptInCurrentProcess(
        context: Context,
        request: EmbeddedScriptRequest,
    ): EmbeddedScriptResult {
        val startedAt = SystemClock.elapsedRealtime()
        val processName = currentProcessName()
        val pid = Process.myPid()
        if (!isEmbeddedProbeProcess(processName)) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = "Embedded script execution must run in isolated process $EMBEDDED_PROBE_PROCESS_SUFFIX; currentProcess=$processName, pid=$pid.",
            )
        }
        if (!BuildConfig.NODEJS_EMBEDDED_SCRIPT_EXECUTION_BUILD_ENABLED) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = embeddedScriptExecutionDisabledMessage(),
            )
        }

        val sourceBytes = request.source.toByteArray(StandardCharsets.UTF_8).size
        if (sourceBytes > EMBEDDED_SCRIPT_SOURCE_MAX_BYTES) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = embeddedScriptSourceTooLargeMessage(request.sourceName, sourceBytes),
            )
        }
        validateEmbeddedScriptModuleSources(request, processName, pid, startedAt)?.let { return it }

        val loadStartedAt = SystemClock.elapsedRealtime()
        val libcxxLoad = loadLibrary("c++_shared")
        val nodeLoad = if (libcxxLoad.loaded) {
            loadLibrary(NativeNodeRuntimeBridge.NODE_LIBRARY_NAME)
        } else {
            LibraryLoad.skipped(NativeNodeRuntimeBridge.NODE_LIBRARY_NAME)
        }
        val bridgeLoad = if (nodeLoad.loaded) {
            loadLibrary(NativeNodeRuntimeBridge.BRIDGE_LIBRARY_NAME)
        } else {
            LibraryLoad.skipped(NativeNodeRuntimeBridge.BRIDGE_LIBRARY_NAME)
        }
        val loadDurationMs = SystemClock.elapsedRealtime() - loadStartedAt
        val loadError = when {
            libcxxLoad.attempted && !libcxxLoad.loaded -> "libc++_shared.so failed to load: ${libcxxLoad.error.toLoadErrorMessage().orEmpty()}"
            nodeLoad.attempted && !nodeLoad.loaded -> "libnode.so failed to load: ${nodeLoad.error.toLoadErrorMessage().orEmpty()}"
            bridgeLoad.attempted && !bridgeLoad.loaded -> "libautojs6-node.so failed to load: ${bridgeLoad.error.toLoadErrorMessage().orEmpty()}"
            else -> null
        }
        if (loadError != null) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = loadError,
                nativeValues = mapOf("load.duration.ms" to loadDurationMs.toString()),
            )
        }

        val nativeCall = runCatching {
            val payload = if (request.runtimeModuleSources.isEmpty()) {
                nativeRunEmbeddedScriptLifecycleWithModules(
                    request.source,
                    request.sourceName,
                    request.workingDirectory,
                    request.moduleSources.keys.toTypedArray(),
                    request.moduleSources.values.toTypedArray(),
                    request.env.keys.toTypedArray(),
                    request.env.values.toTypedArray(),
                    request.esmExperimentalEnabled,
                    request.dynamicImportExperimentalEnabled,
                    request.workerThreadsExperimentalEnabled,
                    request.javaInteropExperimentalEnabled,
                )
            } else {
                nativeRunEmbeddedScriptLifecycleWithRuntimeModules(
                    request.source,
                    request.sourceName,
                    request.workingDirectory,
                    request.moduleSources.keys.toTypedArray(),
                    request.moduleSources.values.toTypedArray(),
                    request.runtimeModuleSources.keys.toTypedArray(),
                    request.runtimeModuleSources.values.toTypedArray(),
                    request.env.keys.toTypedArray(),
                    request.env.values.toTypedArray(),
                    request.esmExperimentalEnabled,
                    request.dynamicImportExperimentalEnabled,
                    request.workerThreadsExperimentalEnabled,
                    request.javaInteropExperimentalEnabled,
                )
            }
            payload ?: emptyArray()
        }
        val nativePayload = nativeCall.getOrElse { throwable ->
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = "Embedded script native runner failed: ${throwable.message ?: throwable.javaClass.name}",
                nativeError = throwable,
                nativeValues = mapOf("load.duration.ms" to loadDurationMs.toString()),
            )
        }
        val nativeValues = parseNativePayload(nativePayload).toMutableMap()
        nativeValues["load.duration.ms"] = loadDurationMs.toString()
        return parseEmbeddedScriptResult(
            request = request,
            processName = processName,
            pid = pid,
            startedAt = startedAt,
            nativeValues = nativeValues,
        )
    }

    private fun parseEmbeddedScriptResult(
        request: EmbeddedScriptRequest,
        processName: String,
        pid: Int,
        startedAt: Long,
        nativeValues: Map<String, String>,
    ): EmbeddedScriptResult {
        val envelopePresent = !nativeValues["embedded_script.result_json"].isNullOrBlank()
        val status = nativeValues["embedded_script.status"].orEmpty()
        val nativeFailure = when {
            status == "failed" -> nativeValues["embedded_script.detail"].takeUnless { it.isNullOrBlank() }
                ?: "Embedded script native lifecycle failed."
            status == "skipped" -> nativeValues["embedded_script.detail"].takeUnless { it.isNullOrBlank() }
                ?: "Embedded script native lifecycle was skipped."
            !envelopePresent -> "Embedded script did not return a result envelope."
            else -> null
        }
        val scriptSucceeded = nativeValues["embedded_script.succeeded"].toBooleanValue()
        val succeeded = nativeFailure == null && scriptSucceeded
        val elapsedMs = nativeValues["timing.total.ms"].toLongValue()
            .takeIf { it > 0L }
            ?: (SystemClock.elapsedRealtime() - startedAt)
        return EmbeddedScriptResult(
            succeeded = succeeded,
            exitCode = nativeValues["embedded_script.exit_code"]?.toIntOrNull()
                ?: if (succeeded) 0 else 1,
            resultText = nativeValues["embedded_script.result_text"].takeUnless { it.isNullOrBlank() },
            stdout = nativeValues["embedded_script.stdout"] ?: nativeValues["stdout_capture.text"].orEmpty(),
            stderr = nativeValues["embedded_script.stderr"] ?: nativeValues["stderr_capture.text"].orEmpty(),
            errorName = nativeValues["embedded_script.error_name"].takeUnless { it.isNullOrBlank() },
            errorMessage = nativeFailure ?: nativeValues["embedded_script.error_message"].takeUnless { it.isNullOrBlank() },
            errorStack = nativeValues["embedded_script.error_stack"].takeUnless { it.isNullOrBlank() },
            errorCode = nativeValues["embedded_script.error_code"].takeUnless { it.isNullOrBlank() },
            elapsedMs = elapsedMs,
            processName = processName,
            pid = pid,
            sourceName = request.sourceName,
            nativeValues = nativeValues,
            timedOut = nativeValues["embedded_script.timed_out"].toBooleanValue(),
            timeoutMs = nativeValues["embedded_script.timeout_ms"].toOptionalLong()?.takeIf { it > 0L },
            workingDirectory = nativeValues["embedded_script.working_directory"].takeUnless { it.isNullOrBlank() }
                ?: request.workingDirectory,
            pendingTimers = nativeValues["embedded_script.pending_timers"].toOptionalBoolean(),
            pendingTimerCount = nativeValues["embedded_script.pending_timer_count"].toOptionalInt(),
            pendingTimeoutCount = nativeValues["embedded_script.pending_timeout_count"].toOptionalInt(),
            pendingIntervalCount = nativeValues["embedded_script.pending_interval_count"].toOptionalInt(),
            pendingImmediateCount = nativeValues["embedded_script.pending_immediate_count"].toOptionalInt(),
            pendingScopedFsCallbacks = nativeValues["embedded_script.pending_scoped_fs_callbacks"].toOptionalInt(),
            pendingWorkers = nativeValues["embedded_script.pending_workers"].toOptionalBoolean(),
            pendingWorkerCount = nativeValues["embedded_script.pending_worker_count"].toOptionalInt(),
            pendingCryptoCallbacks = nativeValues["embedded_script.pending_crypto_callbacks"].toOptionalInt(),
            pendingDnsCallbacks = nativeValues["embedded_script.pending_dns_callbacks"].toOptionalInt(),
            pendingZlibCallbacks = nativeValues["embedded_script.pending_zlib_callbacks"].toOptionalInt(),
            pendingAsyncCallbacks = nativeValues["embedded_script.pending_async_callbacks"].toOptionalInt(),
            pendingCallbacks = nativeValues["embedded_script.pending_callbacks"].toOptionalBoolean(),
        )
    }

    private fun failureEmbeddedScriptResult(
        request: EmbeddedScriptRequest,
        processName: String,
        pid: Int,
        startedAt: Long,
        message: String,
        nativeError: Throwable? = null,
        nativeValues: Map<String, String> = emptyMap(),
    ): EmbeddedScriptResult {
        return EmbeddedScriptResult(
            succeeded = false,
            exitCode = 1,
            resultText = null,
            stdout = nativeValues["stdout_capture.text"].orEmpty(),
            stderr = nativeValues["stderr_capture.text"].orEmpty(),
            errorName = nativeError?.javaClass?.simpleName ?: "EmbeddedScriptExecutionError",
            errorMessage = message,
            errorStack = nativeError?.stackTraceToString(),
            elapsedMs = SystemClock.elapsedRealtime() - startedAt,
            processName = processName,
            pid = pid,
            sourceName = request.sourceName,
            nativeValues = nativeValues,
            workingDirectory = request.workingDirectory,
        )
    }

    fun validateEmbeddedScriptRequestBeforeServiceStart(request: EmbeddedScriptRequest): EmbeddedScriptResult? {
        val startedAt = SystemClock.elapsedRealtime()
        val processName = currentProcessName()
        val pid = Process.myPid()
        if (!BuildConfig.NODEJS_EMBEDDED_SCRIPT_EXECUTION_BUILD_ENABLED) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = embeddedScriptExecutionDisabledMessage(),
            )
        }
        val sourceBytes = request.source.toByteArray(StandardCharsets.UTF_8).size
        if (sourceBytes > EMBEDDED_SCRIPT_SOURCE_MAX_BYTES) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = embeddedScriptSourceTooLargeMessage(request.sourceName, sourceBytes),
            )
        }
        validateEmbeddedScriptModuleSources(request, processName, pid, startedAt)?.let { return it }
        return null
    }

    private fun validateEmbeddedScriptModuleSources(
        request: EmbeddedScriptRequest,
        processName: String,
        pid: Int,
        startedAt: Long,
    ): EmbeddedScriptResult? {
        if (request.moduleSources.size > EMBEDDED_SCRIPT_MODULE_SOURCE_MAX_COUNT) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = "Embedded script module source count is too large for ${request.sourceName}: " +
                        "${request.moduleSources.size} > $EMBEDDED_SCRIPT_MODULE_SOURCE_MAX_COUNT.",
            )
        }
        var totalBytes = 0
        request.moduleSources.forEach { (moduleName, moduleSource) ->
            val moduleBytes = moduleSource.toByteArray(StandardCharsets.UTF_8).size
            if (moduleBytes > EMBEDDED_SCRIPT_MODULE_SOURCE_MAX_BYTES) {
                return failureEmbeddedScriptResult(
                    request = request,
                    processName = processName,
                    pid = pid,
                    startedAt = startedAt,
                    message = "Embedded script module source is too large for $moduleName: " +
                            "$moduleBytes bytes > $EMBEDDED_SCRIPT_MODULE_SOURCE_MAX_BYTES bytes.",
                )
            }
            totalBytes += moduleBytes
        }
        if (totalBytes > EMBEDDED_SCRIPT_MODULE_SOURCES_MAX_BYTES) {
            return failureEmbeddedScriptResult(
                request = request,
                processName = processName,
                pid = pid,
                startedAt = startedAt,
                message = "Embedded script module sources are too large for ${request.sourceName}: " +
                        "$totalBytes bytes > $EMBEDDED_SCRIPT_MODULE_SOURCES_MAX_BYTES bytes.",
            )
        }
        return null
    }

    private fun embeddedScriptExecutionDisabledMessage(): String {
        return "Embedded Node.js script execution is disabled.\n" +
                "Build with:\n" +
                "-Pautojs.nodejs.embedded.script.enabled=true\n" +
                "Current build gate: NODEJS_EMBEDDED_SCRIPT_EXECUTION_BUILD_ENABLED=false; " +
                "backend=${BuildConfig.NODEJS_RUNTIME_BACKEND}."
    }

    private fun embeddedScriptSourceTooLargeMessage(sourceName: String, sourceBytes: Int): String {
        return "Embedded script source is too large for $sourceName: " +
                "$sourceBytes bytes > $EMBEDDED_SCRIPT_SOURCE_MAX_BYTES bytes."
    }

    fun probeEmbeddedRuntime(context: Context): ProbeResult {
        val processName = currentProcessName()
        val pid = Process.myPid()
        if (!isEmbeddedProbeProcess(processName)) {
            val message = "Embedded native probe must run in isolated process $EMBEDDED_PROBE_PROCESS_SUFFIX; currentProcess=$processName, pid=$pid."
            val result = failureProbeResult(context, currentProbeLevel(), processName, pid, message)
            Log.e(TAG, result.formatForLog())
            return result
        }
        return probeEmbeddedRuntimeInCurrentProcess(context, currentProbeLevel())
    }

    fun probeEmbeddedRuntimeInCurrentProcess(
        context: Context,
        probeLevel: Int = currentProbeLevel(),
    ): ProbeResult {
        val probeGates = collectProbeGateState()
        val normalizedProbeLevel = probeLevel.coerceIn(PROBE_LEVEL_MIN, PROBE_LEVEL_MAX)
        val processName = currentProcessName()
        val pid = Process.myPid()
        if (!isEmbeddedProbeProcess(processName)) {
            val message = "Embedded native probe must run in isolated process $EMBEDDED_PROBE_PROCESS_SUFFIX; currentProcess=$processName, pid=$pid."
            val result = failureProbeResult(context, normalizedProbeLevel, processName, pid, message)
            Log.e(TAG, result.formatForLog())
            return result
        }

        if (normalizedProbeLevel == PROBE_LEVEL_KOTLIN_ROUND_TRIP) {
            val result = kotlinRoundTripProbeResult(
                context = context,
                probeLevel = normalizedProbeLevel,
                processName = processName,
                pid = pid,
                totalDurationMs = 0L,
                stageEvents = emptyList(),
            )
            Log.i(TAG, result.formatForLog())
            return result
        }

        val appContext = context.applicationContext
        val startedAt = SystemClock.elapsedRealtime()
        val stageEvents = mutableListOf<String>()
        logStage(stageEvents, processName, pid, normalizedProbeLevel, "probe", "start")
        val probeReadiness = resolveProbeReadiness(normalizedProbeLevel, probeGates)
        val dispatchResult = runNativeProbeForLevel(
            normalizedProbeLevel = normalizedProbeLevel,
            probeGates = probeGates,
            probeReadiness = probeReadiness,
            stageEvents = stageEvents,
            processName = processName,
            pid = pid,
        )
        val libcxxLoad = dispatchResult.libcxxLoad
        val nodeLoad = dispatchResult.nodeLoad
        val bridgeLoad = dispatchResult.bridgeLoad
        val loadDurationMs = dispatchResult.loadDurationMs
        val nativeError = dispatchResult.nativeError
        val nativePayload = dispatchResult.nativePayload
        logStage(stageEvents, processName, pid, normalizedProbeLevel, "probe", "done")

        val nativeValues = parseNativePayload(nativePayload)
        val symbolProbes = parseSymbolProbes(nativeValues)
        val totalDurationMs = SystemClock.elapsedRealtime() - startedAt
        val buildFlags = parseProbeBuildFlags(nativeValues)
        val lifecycleBuildEnabled = buildFlags.lifecycleBuildEnabled
        val isolateBuildEnabled = buildFlags.isolateBuildEnabled
