    private fun appendDynamicProbeStageEvents(
        probeLevel: Int,
        nativeValues: Map<String, String>,
        stageEvents: MutableList<String>,
        probeGates: ProbeGateState,
        buildFlags: ProbeBuildFlags,
        skippedDetails: ProbeSkippedDetails,
    ) {
        fun probe(prefix: String, skippedDetail: String?) = LifecycleProbe(
            status = nativeValues["$prefix.status"] ?: "skipped",
            detail = nativeValues["$prefix.detail"] ?: skippedDetail ?: "not requested at probe level $probeLevel",
            durationMs = nativeValues["timing.$prefix.ms"].toLongValue(),
        )

        fun appendProbe(
            prefix: String,
            requestPrefix: String,
            skippedDetail: String?,
            requested: Boolean,
            buildEnabled: Boolean,
            vararg fields: DynamicStageField,
        ) {
            stageEvents += "$prefix: ${probe(prefix, skippedDetail).format()}"
            fields.forEach { field ->
                stageEvents += "${field.outputKey}=${field.value(nativeValues)}"
            }
            stageEvents += "$requestPrefix.requested=$requested"
            stageEvents += "$requestPrefix.build.enabled=$buildEnabled"
        }

        fun appendInlineProbeIfDefined(): Boolean {
            val definition = INLINE_PROBE_DEFINITIONS.firstOrNull { it.level == probeLevel } ?: return false
            val commonFields = inlineCommonDisplayFields(definition.prefix)
            val commonKeys = commonFields.mapTo(mutableSetOf()) { it.outputKey }
            val payloadFields = nativeValues.keys.asSequence()
                .filter { it.startsWith("${definition.prefix}.") }
                .filterNot { it == "${definition.prefix}.status" || it == "${definition.prefix}.detail" }
                .filterNot { it in commonKeys }
                .sorted()
                .map(::textField)
                .toList()
            appendProbe(
                prefix = definition.prefix,
                requestPrefix = definition.requestPrefix,
                skippedDetail = definition.skippedDetail(skippedDetails),
                requested = definition.requested(probeGates) && probeLevel >= definition.level,
                buildEnabled = definition.buildEnabled(buildFlags),
                fields = (commonFields + payloadFields).toTypedArray(),
            )
            return true
        }

        if (appendInlineProbeIfDefined()) {
            return
        }

        when (probeLevel) {
            PROBE_LEVEL_CONSOLE_FORMAT -> appendProbe(
                prefix = "console_format",
                requestPrefix = "consoleformat",
                skippedDetail = skippedDetails.consoleFormatSkippedDetail,
                requested = probeGates.consoleFormatProbeRequested && probeLevel >= PROBE_LEVEL_CONSOLE_FORMAT,
                buildEnabled = buildFlags.consoleFormatBuildEnabled,
                longField("console_format.source.length"),
                skippedBlankField("console_format.load_environment.result"),
                skippedBlankField("console_format.spin_event_loop.result"),
                textField("console_format.result_text"),
                textField("console_format.stdout_captured"),
                textField("console_format.stderr_captured"),
                boolField("console_format.stdout_contains_primitive"),
                boolField("console_format.stdout_contains_object"),
                boolField("console_format.stderr_contains_error"),
                textField("console_format.stdout_fd"),
                textField("console_format.stderr_fd"),
            )
            PROBE_LEVEL_CONSOLE_REJECTION -> appendProbe(
                prefix = "console_rejection",
                requestPrefix = "consolerejection",
                skippedDetail = skippedDetails.consoleRejectionSkippedDetail,
                requested = probeGates.consoleRejectionProbeRequested && probeLevel >= PROBE_LEVEL_CONSOLE_REJECTION,
                buildEnabled = buildFlags.consoleRejectionBuildEnabled,
                longField("console_rejection.source.length"),
                skippedBlankField("console_rejection.load_environment.result"),
                skippedBlankField("console_rejection.spin_event_loop.result"),
                textField("console_rejection.result_text"),
                textField("console_rejection.stderr_captured"),
                boolField("console_rejection.stderr_contains_caught"),
                boolField("console_rejection.stderr_contains_rejection"),
                boolField("console_rejection.rejection_seen"),
                textField("console_rejection.stderr_fd"),
                textField("console_rejection.stderr_write_type"),
            )
            PROBE_LEVEL_CONSOLE_UNCAUGHT -> appendProbe(
                prefix = "console_uncaught",
                requestPrefix = "consoleuncaught",
                skippedDetail = skippedDetails.consoleUncaughtSkippedDetail,
                requested = probeGates.consoleUncaughtProbeRequested && probeLevel >= PROBE_LEVEL_CONSOLE_UNCAUGHT,
                buildEnabled = buildFlags.consoleUncaughtBuildEnabled,
                longField("console_uncaught.source.length"),
                skippedBlankField("console_uncaught.load_environment.result"),
                skippedBlankField("console_uncaught.spin_event_loop.result"),
                textField("console_uncaught.result_text"),
                textField("console_uncaught.stderr_captured"),
                boolField("console_uncaught.stderr_contains_uncaught"),
                boolField("console_uncaught.uncaught_seen"),
                textField("console_uncaught.stderr_fd"),
                textField("console_uncaught.stderr_write_type"),
            )
            PROBE_LEVEL_SCHEDULING -> appendProbe(
                prefix = "scheduling",
                requestPrefix = "scheduling",
                skippedDetail = skippedDetails.schedulingSkippedDetail,
                requested = probeGates.schedulingProbeRequested && probeLevel >= PROBE_LEVEL_SCHEDULING,
                buildEnabled = buildFlags.schedulingBuildEnabled,
                longField("scheduling.source.length"),
                skippedMissingField("scheduling.load_environment.result"),
