    private fun textField(key: String) = DynamicStageField(key, DynamicStageValueKind.Text)

    private fun boolField(key: String) = DynamicStageField(key, DynamicStageValueKind.Boolean)

    private fun longField(key: String) = DynamicStageField(key, DynamicStageValueKind.LongOrZero)

    private fun skippedMissingField(key: String) = DynamicStageField(key, DynamicStageValueKind.SkippedIfMissing)

    private fun skippedBlankField(key: String) = DynamicStageField(key, DynamicStageValueKind.SkippedIfBlank)

    private fun inlineCommonDisplayFields(prefix: String) = listOf(
        longField("$prefix.source.length"),
        longField("$prefix.bootstrap_source.length"),
        longField("$prefix.script_source.length"),
        skippedMissingField("$prefix.load_environment.result"),
        skippedMissingField("$prefix.spin_event_loop.result"),
        textField("$prefix.result_text"),
        textField("$prefix.execution_mode"),
        textField("$prefix.source_kind"),
        boolField("$prefix.user_source_used"),
        boolField("$prefix.user_file_read"),
    )

    private fun parseCoreLifecycleProbes(
        nativeValues: Map<String, String>,
        normalizedProbeLevel: Int,
        skippedDetails: ProbeSkippedDetails,
    ): ParsedCoreLifecycleProbes {
        fun probe(
            prefix: String,
            timingKey: String,
            skippedDetail: String?,
            defaultDetail: String,
        ): LifecycleProbe = LifecycleProbe(
            status = nativeValues["$prefix.status"] ?: "skipped",
            detail = nativeValues["$prefix.detail"] ?: skippedDetail ?: defaultDetail,
            durationMs = nativeValues[timingKey].toLongValue(),
        )

        val notRequested = "not requested at probe level $normalizedProbeLevel"
        return ParsedCoreLifecycleProbes(
            uvLoopInitProbe = probe("uv.loop.init", "timing.uv_loop_init.ms", skippedDetails.uvLoopSkippedDetail, notRequested),
            uvLoopCloseProbe = probe("uv.loop.close", "timing.uv_loop_close.ms", skippedDetails.uvLoopSkippedDetail, "uv_loop_init was not called"),
            initializeProbe = probe("initialize", "timing.initialize.ms", skippedDetails.lifecycleSkippedDetail, notRequested),
            teardownProbe = probe("teardown", "timing.teardown.ms", skippedDetails.lifecycleSkippedDetail, "InitializeOncePerProcess was not called"),
            platformCreateProbe = probe(
                prefix = "platform.create",
                timingKey = "timing.platform_create.ms",
                skippedDetail = skippedDetails.isolateSkippedDetail ?: skippedDetails.v8SkippedDetail,
                defaultDetail = notRequested,
            ),
            v8InitializePlatformProbe = probe("v8.initialize_platform", "timing.v8_initialize_platform.ms", skippedDetails.v8SkippedDetail, notRequested),
            v8InitializeProbe = probe("v8.initialize", "timing.v8_initialize.ms", skippedDetails.v8SkippedDetail, notRequested),
            allocatorCreateProbe = probe("allocator.create", "timing.allocator_create.ms", skippedDetails.isolateSkippedDetail, notRequested),
            isolateCreateProbe = probe("isolate.create", "timing.isolate_create.ms", skippedDetails.isolateSkippedDetail, notRequested),
            isolateDisposeProbe = probe("isolate.dispose", "timing.isolate_dispose.ms", skippedDetails.isolateSkippedDetail, "isolate was not created"),
            uvCloseProbe = probe("uv.close", "timing.uv_close.ms", skippedDetails.uvCloseSkippedDetail, notRequested),
            uvRunProbe = probe("uv.run", "timing.uv_run.ms", skippedDetails.uvRunSkippedDetail, notRequested),
