    private fun parseUvProbePayloads(
        nativeValues: Map<String, String>,
        skippedDetails: ProbeSkippedDetails,
    ): ParsedUvProbePayloads {
        return ParsedUvProbePayloads(
            uvDiagnosticsBeforeClose = parseUvDiagnosticsSnapshot(nativeValues, "before_close", skippedDetails.uvDiagnosticsSkippedDetail),
            uvDiagnosticsAfterClose = parseUvDiagnosticsSnapshot(nativeValues, "after_close", skippedDetails.uvDiagnosticsSkippedDetail),
            uvDiagnosticsAfterUvClose = parseUvDiagnosticsSnapshot(nativeValues, "after_uv_close", skippedDetails.uvDiagnosticsSkippedDetail),
            uvDiagnosticsAfterLoopClose = parseUvDiagnosticsSnapshot(nativeValues, "after_loop_close", skippedDetails.uvDiagnosticsSkippedDetail),
            uvCloseStats = UvCloseStats(
                attempted = nativeValues["uv.close.attempted"]?.toIntOrNull() ?: 0,
                succeeded = nativeValues["uv.close.succeeded"]?.toIntOrNull() ?: 0,
                skipped = nativeValues["uv.close.skipped"]?.toIntOrNull() ?: 0,
                failed = nativeValues["uv.close.failed"]?.toIntOrNull() ?: 0,
            ),
            uvRunStats = UvRunStats(
                mode = nativeValues["uv.run.mode"] ?: "UV_RUN_NOWAIT",
                maxIterations = nativeValues["uv.run.max_iterations"]?.toIntOrNull() ?: 0,
                completedIterations = nativeValues["uv.run.completed_iterations"]?.toIntOrNull() ?: 0,
                iterations = parseUvRunIterations(nativeValues, skippedDetails.uvRunSkippedDetail),
            ),
        )
    }

    private fun buildDynamicProbeErrorMessages(
        payloads: ParsedDynamicProbePayloads,
    ): DynamicProbeErrorMessages {
        fun failed(probe: LifecycleProbe, label: String): String? {
            return if (probe.status == "failed") {
                "$label probe failed: ${probe.detail.orEmpty()}"
            } else {
                null
            }
        }

        return DynamicProbeErrorMessages(
            schedulingErrorMessage = failed(payloads.schedulingProbe, "scheduling globals"),
            schedulingOrderErrorMessage = failed(payloads.schedulingOrderProbe, "scheduling order"),
