        !probeGates.pluginCancelProbeRequested -> "runtime property $PLUGIN_CANCEL_PROBE_PROPERTY=true is not set"
        !probeGates.pluginDisposeProbeRequested -> "runtime property $PLUGIN_DISPOSE_PROBE_PROPERTY=true is not set"
        !probeGates.pluginLifecycleProbeRequested -> "runtime property $PLUGIN_LIFECYCLE_PROBE_PROPERTY=true is not set"
        !probeGates.pluginInvalidRequestProbeRequested -> "runtime property $PLUGIN_INVALID_REQUEST_PROBE_PROPERTY=true is not set"
        !probeGates.pluginStateMachineProbeRequested -> "runtime property $PLUGIN_STATE_MACHINE_PROBE_PROPERTY=true is not set"
        !probeGates.pluginTimeoutProbeRequested -> "runtime property $PLUGIN_TIMEOUT_PROBE_PROPERTY=true is not set"
        !probeGates.pluginCrashProbeRequested -> "runtime property $PLUGIN_CRASH_PROBE_PROPERTY=true is not set"
        !probeGates.pluginBackpressureProbeRequested -> "runtime property $PLUGIN_BACKPRESSURE_PROBE_PROPERTY=true is not set"
        !probeGates.pluginNegotiationProbeRequested -> "runtime property $PLUGIN_NEGOTIATION_PROBE_PROPERTY=true is not set"
        !probeGates.pluginPermissionProbeRequested -> "runtime property $PLUGIN_PERMISSION_PROBE_PROPERTY=true is not set"
        !probeGates.pluginManifestProbeRequested -> "runtime property $PLUGIN_MANIFEST_PROBE_PROPERTY=true is not set"
        !probeGates.pluginAbiProbeRequested -> "runtime property $PLUGIN_ABI_PROBE_PROPERTY=true is not set"
        !probeGates.pluginLibraryProbeRequested -> "runtime property $PLUGIN_LIBRARY_PROBE_PROPERTY=true is not set"
        !pluginLibraryBuildEnabled -> "compile-time lifecycle probe is disabled"
        else -> null
    }

    private fun buildPostLibraryPluginSkippedDetail(
        normalizedProbeLevel: Int,
        targetProbeLevel: Int,
        probeGates: ProbeGateState,
        targetBuildEnabled: Boolean,
    ): String? {
        if (normalizedProbeLevel != targetProbeLevel) {
            return null
        }
        return buildPluginLibrarySkippedDetail(
            normalizedProbeLevel = PROBE_LEVEL_PLUGIN_LIBRARY,
            probeGates = probeGates,
            pluginLibraryBuildEnabled = true,
        ) ?: buildPostLibraryPluginGateRequirements(probeGates)
            .firstOrNull { it.level <= targetProbeLevel && !it.requested }
            ?.let { "runtime property ${it.property}=true is not set" }
            ?: when {
                !targetBuildEnabled -> "compile-time lifecycle probe is disabled"
                else -> null
            }
    }

