    private fun buildInlineProbeGateRequirements(probeGates: ProbeGateState): List<ProbeGateRequirement> =
        INLINE_PROBE_DEFINITIONS.map { definition ->
            ProbeGateRequirement(definition.level, definition.propertyName, definition.requested(probeGates))
        }

    private fun buildPostLibraryPluginGateRequirements(probeGates: ProbeGateState): List<ProbeGateRequirement> = listOf(
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_INSTANCE, PLUGIN_INSTANCE_PROBE_PROPERTY, probeGates.pluginInstanceProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_SESSION, PLUGIN_SESSION_PROBE_PROPERTY, probeGates.pluginSessionProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_QUEUE, PLUGIN_QUEUE_PROBE_PROPERTY, probeGates.pluginQueueProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_CONCURRENCY, PLUGIN_CONCURRENCY_PROBE_PROPERTY, probeGates.pluginConcurrencyProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_RACE, PLUGIN_RACE_PROBE_PROPERTY, probeGates.pluginRaceProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_SHUTDOWN, PLUGIN_SHUTDOWN_PROBE_PROPERTY, probeGates.pluginShutdownProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_HEARTBEAT, PLUGIN_HEARTBEAT_PROBE_PROPERTY, probeGates.pluginHeartbeatProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_HEALTH, PLUGIN_HEALTH_PROBE_PROPERTY, probeGates.pluginHealthProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_TELEMETRY, PLUGIN_TELEMETRY_PROBE_PROPERTY, probeGates.pluginTelemetryProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_DIAGNOSTICS, PLUGIN_DIAGNOSTICS_PROBE_PROPERTY, probeGates.pluginDiagnosticsProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_RECOVERY, PLUGIN_RECOVERY_PROBE_PROPERTY, probeGates.pluginRecoveryProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_RESTART, PLUGIN_RESTART_PROBE_PROPERTY, probeGates.pluginRestartProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_RESTART_BUDGET, PLUGIN_RESTART_BUDGET_PROBE_PROPERTY, probeGates.pluginRestartBudgetProbeRequested),
        ProbeGateRequirement(PROBE_LEVEL_PLUGIN_QUARANTINE, PLUGIN_QUARANTINE_PROBE_PROPERTY, probeGates.pluginQuarantineProbeRequested),
