    private fun runNativeProbeForLevel(
        normalizedProbeLevel: Int,
        probeGates: ProbeGateState,
        probeReadiness: ProbeReadiness,
        stageEvents: MutableList<String>,
        processName: String,
        pid: Int,
    ): ProbeDispatchResult {
        var libcxxLoad = LibraryLoad.skipped("c++_shared")
        var nodeLoad = LibraryLoad.skipped(NativeNodeRuntimeBridge.NODE_LIBRARY_NAME)
        var bridgeLoad = LibraryLoad.skipped(NativeNodeRuntimeBridge.BRIDGE_LIBRARY_NAME)
        var loadDurationMs = 0L
        var nativeError: Throwable? = null
        var nativePayload = emptyArray<String>()

        val skippedStage = probeReadiness.skippedStage
        if (skippedStage != null) {
            logStage(stageEvents, processName, pid, normalizedProbeLevel, skippedStage, "skipped")
        } else when (normalizedProbeLevel) {
            PROBE_LEVEL_BRIDGE_PING -> {
                val loadStartedAt = SystemClock.elapsedRealtime()
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "bridge.load", "start")
                bridgeLoad = loadLibrary(NativeNodeRuntimeBridge.BRIDGE_LIBRARY_NAME)
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "bridge.load", if (bridgeLoad.loaded) "done" else "failed")
                loadDurationMs = SystemClock.elapsedRealtime() - loadStartedAt
                if (bridgeLoad.loaded) {
                    logStage(stageEvents, processName, pid, normalizedProbeLevel, "bridge.ping", "start")
                    nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "bridge.ping") {
                        nativeEmbeddedProbePing() ?: emptyArray()
                    }.also {
                        nativeError = it.error
                    }.payload
                }
            }
            PROBE_LEVEL_LOAD_LIBNODE -> {
                val loadStartedAt = SystemClock.elapsedRealtime()
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libcxx.load", "start")
                libcxxLoad = loadLibrary("c++_shared")
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libcxx.load", if (libcxxLoad.loaded) "done" else "failed")
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libnode.load", "start")
                nodeLoad = loadLibrary(NativeNodeRuntimeBridge.NODE_LIBRARY_NAME)
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libnode.load", if (nodeLoad.loaded) "done" else "failed")
                loadDurationMs = SystemClock.elapsedRealtime() - loadStartedAt
            }
            PROBE_LEVEL_LIBNODE_HANDLE,
            PROBE_LEVEL_DLSYM,
            PROBE_LEVEL_LIFECYCLE,
            PROBE_LEVEL_ISOLATE,
            PROBE_LEVEL_UV_ISOLATE,
            PROBE_LEVEL_V8,
            PROBE_LEVEL_UV_DIAGNOSTICS,
            PROBE_LEVEL_UV_CLOSE,
            PROBE_LEVEL_UV_RUN,
            PROBE_LEVEL_ISOLATE_DATA,
            PROBE_LEVEL_ENVIRONMENT,
            PROBE_LEVEL_LOAD_ENVIRONMENT,
            PROBE_LEVEL_SPIN_EVENT_LOOP,
            PROBE_LEVEL_INLINE_JS,
            PROBE_LEVEL_PROCESS_JS,
            PROBE_LEVEL_CONSOLE_JS,
            PROBE_LEVEL_STDOUT_CAPTURE,
            PROBE_LEVEL_JS_RESULT,
            PROBE_LEVEL_STDOUT_WRITE,
            PROBE_LEVEL_CONSOLE_DIAGNOSTICS,
            PROBE_LEVEL_CONSOLE_STREAM,
            PROBE_LEVEL_CONSOLE_SHAPE,
            PROBE_LEVEL_CONSOLE_REPLACE,
            PROBE_LEVEL_CONSOLE_FAMILY,
            PROBE_LEVEL_CONSOLE_FORMAT,
            PROBE_LEVEL_CONSOLE_REJECTION,
            PROBE_LEVEL_CONSOLE_UNCAUGHT,
            PROBE_LEVEL_SCHEDULING,
            PROBE_LEVEL_SCHEDULING_ORDER,
            PROBE_LEVEL_ASYNC_CONSOLE,
            PROBE_LEVEL_ASYNC_ERROR,
            PROBE_LEVEL_BOOTSTRAP,
            PROBE_LEVEL_BOOTSTRAP_SCRIPT,
            PROBE_LEVEL_SCRIPT_COMPLETION,
            PROBE_LEVEL_SCRIPT_FAILURE,
            PROBE_LEVEL_COMPLETION_DRAIN,
            PROBE_LEVEL_POST_COMPLETION_ERROR,
            PROBE_LEVEL_OUTPUT_EVENTS,
            PROBE_LEVEL_OUTPUT_ENVELOPE,
            PROBE_LEVEL_SCRIPT_CANCEL,
            PROBE_LEVEL_CAPABILITY_DESCRIPTOR,
            PROBE_LEVEL_PLUGIN_CONTRACT,
            PROBE_LEVEL_PLUGIN_REQUEST,
            PROBE_LEVEL_PLUGIN_EVENTS,
            PROBE_LEVEL_PLUGIN_FAILURE,
            PROBE_LEVEL_PLUGIN_CANCEL,
            PROBE_LEVEL_PLUGIN_DISPOSE,
            PROBE_LEVEL_PLUGIN_LIFECYCLE,
            PROBE_LEVEL_PLUGIN_INVALID_REQUEST,
            PROBE_LEVEL_PLUGIN_STATE_MACHINE,
            PROBE_LEVEL_PLUGIN_TIMEOUT,
            PROBE_LEVEL_PLUGIN_CRASH,
            PROBE_LEVEL_PLUGIN_BACKPRESSURE,
            PROBE_LEVEL_PLUGIN_NEGOTIATION,
            PROBE_LEVEL_PLUGIN_PERMISSION,
            PROBE_LEVEL_PLUGIN_MANIFEST,
            PROBE_LEVEL_PLUGIN_ABI,
            PROBE_LEVEL_PLUGIN_LIBRARY,
            PROBE_LEVEL_PLUGIN_INSTANCE,
            PROBE_LEVEL_PLUGIN_SESSION,
            PROBE_LEVEL_PLUGIN_QUEUE,
            PROBE_LEVEL_PLUGIN_CONCURRENCY,
            PROBE_LEVEL_PLUGIN_RACE,
            PROBE_LEVEL_PLUGIN_SHUTDOWN,
            PROBE_LEVEL_PLUGIN_HEARTBEAT,
            PROBE_LEVEL_PLUGIN_HEALTH,
            PROBE_LEVEL_PLUGIN_TELEMETRY,
            PROBE_LEVEL_PLUGIN_DIAGNOSTICS,
            PROBE_LEVEL_PLUGIN_RECOVERY,
            PROBE_LEVEL_PLUGIN_RESTART,
            PROBE_LEVEL_PLUGIN_RESTART_BUDGET,
            PROBE_LEVEL_PLUGIN_QUARANTINE,
            PROBE_LEVEL_SCRIPT_DESCRIPTOR,
            PROBE_LEVEL_SCRIPT_NORMALIZATION,
            PROBE_LEVEL_SCRIPT_CONTEXT,
            PROBE_LEVEL_SCRIPT_RESULT_V2,
            PROBE_LEVEL_SCRIPT_CANCELLATION_TOKEN,
            PROBE_LEVEL_SCRIPT_TIMEOUT_POLICY,
            PROBE_LEVEL_SCRIPT_MEMORY_POLICY,
            PROBE_LEVEL_SCRIPT_PREFLIGHT_SUMMARY,
            in PROBE_LEVEL_INLINE_CONSTANT..PROBE_LEVEL_EMBEDDED_MVP_GO_NO_GO -> {
                val loadStartedAt = SystemClock.elapsedRealtime()
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libcxx.load", "start")
                libcxxLoad = loadLibrary("c++_shared")
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libcxx.load", if (libcxxLoad.loaded) "done" else "failed")
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libnode.load", "start")
                nodeLoad = loadLibrary(NativeNodeRuntimeBridge.NODE_LIBRARY_NAME)
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "libnode.load", if (nodeLoad.loaded) "done" else "failed")
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "bridge.load", "start")
                bridgeLoad = loadLibrary(NativeNodeRuntimeBridge.BRIDGE_LIBRARY_NAME)
                logStage(stageEvents, processName, pid, normalizedProbeLevel, "bridge.load", if (bridgeLoad.loaded) "done" else "failed")
                loadDurationMs = SystemClock.elapsedRealtime() - loadStartedAt
                if (bridgeLoad.loaded) {
                    when (normalizedProbeLevel) {
                        PROBE_LEVEL_LIBNODE_HANDLE -> {
                            logStage(stageEvents, processName, pid, normalizedProbeLevel, "libnode.handle", "start")
                            nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "libnode.handle") {
                                nativeEmbeddedProbeLibnodeHandle() ?: emptyArray()
                            }.also {
                                nativeError = it.error
                            }.payload
                        }
                        PROBE_LEVEL_DLSYM -> {
                            logStage(stageEvents, processName, pid, normalizedProbeLevel, "dlsym", "start")
                            nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "dlsym") {
                                nativeEmbeddedProbeDlsym() ?: emptyArray()
                            }.also {
                                nativeError = it.error
                            }.payload
                        }
                        PROBE_LEVEL_LIFECYCLE -> {
                            if (probeGates.lifecycleProbeRequested && BuildConfig.NODEJS_EMBEDDED_PROBE_LIFECYCLE_BUILD_ENABLED) {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "lifecycle", "start")
                                nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "lifecycle") {
                                    nativeEmbeddedProbeLifecycle() ?: emptyArray()
                                }.also {
                                    nativeError = it.error
                                }.payload
                            } else {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "lifecycle", "skipped")
                            }
                        }
                        PROBE_LEVEL_ISOLATE -> {
                            if (probeGates.lifecycleProbeRequested && probeGates.isolateProbeRequested && BuildConfig.NODEJS_EMBEDDED_PROBE_LIFECYCLE_BUILD_ENABLED) {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "isolate.lifecycle", "start")
                                nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "isolate.lifecycle") {
                                    nativeEmbeddedProbeIsolateLifecycle() ?: emptyArray()
                                }.also {
                                    nativeError = it.error
                                }.payload
                            } else {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "isolate.lifecycle", "skipped")
                            }
                        }
                        PROBE_LEVEL_UV_ISOLATE -> {
                            if (probeGates.lifecycleProbeRequested && probeGates.isolateProbeRequested && probeGates.uvLoopProbeRequested && BuildConfig.NODEJS_EMBEDDED_PROBE_LIFECYCLE_BUILD_ENABLED) {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "uv.isolate.lifecycle", "start")
                                nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "uv.isolate.lifecycle") {
                                    nativeEmbeddedProbeUvIsolateLifecycle() ?: emptyArray()
                                }.also {
                                    nativeError = it.error
                                }.payload
                            } else {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "uv.isolate.lifecycle", "skipped")
                            }
                        }
                        PROBE_LEVEL_V8 -> {
                            if (probeGates.lifecycleProbeRequested && probeGates.v8ProbeRequested && BuildConfig.NODEJS_EMBEDDED_PROBE_LIFECYCLE_BUILD_ENABLED) {
                                if (probeGates.isolateProbeRequested && probeGates.uvLoopProbeRequested) {
                                    logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.isolate.lifecycle", "start")
                                    nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.isolate.lifecycle") {
                                        nativeEmbeddedProbeV8UvIsolateLifecycle() ?: emptyArray()
                                    }.also {
                                        nativeError = it.error
                                    }.payload
                                } else {
                                    logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.lifecycle", "start")
                                    nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "v8.lifecycle") {
                                        nativeEmbeddedProbeV8Lifecycle() ?: emptyArray()
                                    }.also {
                                        nativeError = it.error
                                    }.payload
                                }
                            } else {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.lifecycle", "skipped")
                            }
                        }
                        PROBE_LEVEL_UV_DIAGNOSTICS -> {
                            if (probeGates.lifecycleProbeRequested &&
                                probeGates.v8ProbeRequested &&
                                probeGates.isolateProbeRequested &&
                                probeGates.uvLoopProbeRequested &&
                                probeGates.uvDiagnosticsProbeRequested &&
                                BuildConfig.NODEJS_EMBEDDED_PROBE_LIFECYCLE_BUILD_ENABLED
                            ) {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.diagnostics.lifecycle", "start")
                                nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.diagnostics.lifecycle") {
                                    nativeEmbeddedProbeV8UvDiagnosticsLifecycle() ?: emptyArray()
                                }.also {
                                    nativeError = it.error
                                }.payload
                            } else {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.diagnostics.lifecycle", "skipped")
                            }
                        }
                        PROBE_LEVEL_UV_CLOSE -> {
                            if (probeGates.lifecycleProbeRequested &&
                                probeGates.v8ProbeRequested &&
                                probeGates.isolateProbeRequested &&
                                probeGates.uvLoopProbeRequested &&
                                probeGates.uvDiagnosticsProbeRequested &&
                                probeGates.uvCloseProbeRequested &&
                                BuildConfig.NODEJS_EMBEDDED_PROBE_LIFECYCLE_BUILD_ENABLED
                            ) {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.close.lifecycle", "start")
