                                nativePayload = runNativeProbe(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.inline_sms_telephony_denied.lifecycle") {
                                    nativeEmbeddedProbeV8UvInlineSmsTelephonyDeniedLifecycle() ?: emptyArray()
                                }.also {
                                    nativeError = it.error
                                }.payload
                            } else {
                                logStage(stageEvents, processName, pid, normalizedProbeLevel, "v8.uv.inline_sms_telephony_denied.lifecycle", "skipped")
                            }
                        }
                    }
                }
            }
        }
        return ProbeDispatchResult(
            libcxxLoad = libcxxLoad,
            nodeLoad = nodeLoad,
            bridgeLoad = bridgeLoad,
            loadDurationMs = loadDurationMs,
            nativePayload = nativePayload,
            nativeError = nativeError,
        )
    }
