    private fun isProbePropertyEnabled(propertyName: String): Boolean {
        val value = System.getProperty(propertyName)?.trim().orEmpty()
        return value.equals("true", ignoreCase = true) ||
                value.equals("yes", ignoreCase = true) ||
                value == "1"
    }

