    fun currentProbeLevel(): Int {
        val value = System.getProperty(PROBE_LEVEL_PROPERTY)
            ?.trim()
            ?.toIntOrNull()
            ?: BuildConfig.NODEJS_EMBEDDED_PROBE_LEVEL
        return value.coerceIn(PROBE_LEVEL_MIN, PROBE_LEVEL_MAX)
    }

    fun currentProbeTimeoutMs(): Long {
        val value = System.getProperty(PROBE_TIMEOUT_MS_PROPERTY)
            ?.trim()
            ?.toLongOrNull()
            ?: BuildConfig.NODEJS_EMBEDDED_PROBE_TIMEOUT_MS
        return value.coerceAtLeast(1L)
    }

    private fun currentProcessName(): String = runCatching { App.getProcessNameCompat() }
        .getOrElse { "unknown" }

    fun isEmbeddedProbeProcess(processName: String): Boolean =
        processName.endsWith(EMBEDDED_PROBE_PROCESS_SUFFIX)

    private fun logStage(
        stageEvents: MutableList<String>,
        processName: String,
        pid: Int,
        probeLevel: Int,
        stage: String,
        state: String,
    ) {
        val event = "stage.$state=$stage"
        stageEvents += event
        Log.i(TAG, "processName=$processName pid=$pid level=$probeLevel $event")
    }

    private fun runNativeProbe(
        stageEvents: MutableList<String>,
        processName: String,
        pid: Int,
        probeLevel: Int,
        stage: String,
        block: () -> Array<String>,
    ): NativeProbeCall {
        return runCatching { block() }
            .fold(
                onSuccess = {
                    logStage(stageEvents, processName, pid, probeLevel, stage, "done")
                    NativeProbeCall(payload = it, error = null)
                },
                onFailure = {
                    logStage(stageEvents, processName, pid, probeLevel, stage, "failed")
                    NativeProbeCall(payload = emptyArray(), error = it)
                },
            )
    }

    private fun loadLibrary(name: String): LibraryLoad = try {
        System.loadLibrary(name)
        LibraryLoad(name = name, loaded = true, attempted = true)
    } catch (e: UnsatisfiedLinkError) {
        LibraryLoad(name = name, loaded = false, attempted = true, error = e)
    } catch (e: SecurityException) {
        LibraryLoad(name = name, loaded = false, attempted = true, error = e)
    }

    private fun parseNativePayload(payload: Array<String>): Map<String, String> {
        return payload.mapNotNull { entry ->
            val separator = entry.indexOf('=')
            if (separator <= 0) {
                null
            } else {
                entry.substring(0, separator) to entry.substring(separator + 1)
            }
        }.toMap()
    }

    private fun parseSymbolProbes(values: Map<String, String>): List<SymbolProbe> {
        val count = values["symbol.count"]?.toIntOrNull() ?: return emptyList()
        return (0 until count).map { index ->
            SymbolProbe(
                description = values["symbol.$index.description"].orEmpty(),
                found = values["symbol.$index.found"].toBooleanValue(),
                resolvedSymbol = values["symbol.$index.resolved"].takeUnless { it.isNullOrBlank() },
                candidates = values["symbol.$index.candidates"]
                    ?.split('|')
                    ?.filter { it.isNotBlank() }
                    .orEmpty(),
            )
        }
    }

    private fun parseUvDiagnosticsSnapshot(
        values: Map<String, String>,
        phase: String,
        skippedDetail: String?,
    ): UvDiagnosticsSnapshot {
        val prefix = "uv.diagnostics.$phase"
        val typePrefix = "$prefix.type."
        val typeCounts = values
            .filterKeys { it.startsWith(typePrefix) }
            .mapNotNull { (key, value) ->
                val type = key.removePrefix(typePrefix).takeIf { it.isNotBlank() } ?: return@mapNotNull null
                val count = value.toIntOrNull() ?: return@mapNotNull null
                type to count
            }
            .sortedBy { it.first }
            .toMap()
        val sampleCount = values["$prefix.handle.sample.count"]?.toIntOrNull() ?: 0
        val handles = (0 until sampleCount).mapNotNull { index ->
            val handlePrefix = "$prefix.handle.$index"
            val type = values["$handlePrefix.type"] ?: return@mapNotNull null
            UvHandleDiagnostic(
                address = values["$handlePrefix.address"].orEmpty(),
                type = type,
                active = values["$handlePrefix.active"].toBooleanValue(),
                closing = values["$handlePrefix.closing"].toBooleanValue(),
            )
        }
        return UvDiagnosticsSnapshot(
            status = values["$prefix.status"] ?: "skipped",
            detail = values["$prefix.detail"] ?: skippedDetail ?: "not requested",
            count = values["$prefix.count"]?.toIntOrNull() ?: 0,
            active = values["$prefix.active"]?.toIntOrNull() ?: 0,
            closing = values["$prefix.closing"]?.toIntOrNull() ?: 0,
            typeCounts = typeCounts,
            handles = handles,
            durationMs = values["timing.uv_diagnostics_$phase.ms"].toLongValue(),
        )
    }

    private fun parseUvRunIterations(
        values: Map<String, String>,
        skippedDetail: String?,
    ): List<UvRunIteration> {
        val maxIterations = values["uv.run.max_iterations"]?.toIntOrNull() ?: return emptyList()
        return (0 until maxIterations).mapNotNull { index ->
            val prefix = "uv.run.iteration.$index"
            val rc = values["$prefix.rc"]?.toIntOrNull() ?: return@mapNotNull null
            val diagnostics = parseUvDiagnosticsSnapshot(values, "after_run_$index", skippedDetail)
            UvRunIteration(
                index = index,
                rc = rc,
                handleCount = values["$prefix.handle.count"]?.toIntOrNull() ?: diagnostics.count,
                active = values["$prefix.handle.active"]?.toIntOrNull() ?: diagnostics.active,
                closing = values["$prefix.handle.closing"]?.toIntOrNull() ?: diagnostics.closing,
                diagnostics = diagnostics,
            )
        }
    }

    private fun buildProbeError(
        probeLevel: Int,
        libcxxLoad: LibraryLoad,
        nodeLoad: LibraryLoad,
        bridgeLoad: LibraryLoad,
        nativeError: Throwable?,
        libnodeHandleAvailable: Boolean,
        libnodeHandleError: String?,
        nodeStartFound: Boolean,
        symbolProbes: List<SymbolProbe>,
        uvLoopInitProbe: LifecycleProbe,
        uvLoopCloseProbe: LifecycleProbe,
        initializeProbe: LifecycleProbe,
        teardownProbe: LifecycleProbe,
        platformCreateProbe: LifecycleProbe,
        v8InitializePlatformProbe: LifecycleProbe,
        v8InitializeProbe: LifecycleProbe,
        allocatorCreateProbe: LifecycleProbe,
        isolateCreateProbe: LifecycleProbe,
        isolateDisposeProbe: LifecycleProbe,
        uvCloseProbe: LifecycleProbe,
        uvRunProbe: LifecycleProbe,
        isolateDataCreateProbe: LifecycleProbe,
        isolateDataFreeProbe: LifecycleProbe,
        environmentCreateProbe: LifecycleProbe,
        environmentFreeProbe: LifecycleProbe,
        loadEnvironmentProbe: LifecycleProbe,
        spinEventLoopProbe: LifecycleProbe,
        inlineJsProbe: LifecycleProbe,
        processJsProbe: LifecycleProbe,
        consoleJsProbe: LifecycleProbe,
        stdoutCaptureProbe: LifecycleProbe,
        jsResultProbe: LifecycleProbe,
        stdoutWriteProbe: LifecycleProbe,
        consoleDiagnosticsProbe: LifecycleProbe,
        consoleStreamProbe: LifecycleProbe,
        consoleShapeProbe: LifecycleProbe,
        consoleReplaceProbe: LifecycleProbe,
        consoleFamilyProbe: LifecycleProbe,
        consoleFormatProbe: LifecycleProbe,
        consoleRejectionProbe: LifecycleProbe,
        consoleUncaughtProbe: LifecycleProbe,
        uvDiagnosticsBeforeClose: UvDiagnosticsSnapshot,
        uvDiagnosticsAfterClose: UvDiagnosticsSnapshot,
        uvDiagnosticsAfterUvClose: UvDiagnosticsSnapshot,
        uvDiagnosticsAfterLoopClose: UvDiagnosticsSnapshot,
    ): String? {
        val errors = mutableListOf<String>()
        if (probeLevel >= PROBE_LEVEL_LOAD_LIBNODE && libcxxLoad.attempted && !libcxxLoad.loaded) {
            errors += "libc++_shared.so failed to load: ${libcxxLoad.error.toLoadErrorMessage().orEmpty()}"
        }
        if (bridgeLoad.attempted && !bridgeLoad.loaded) {
            errors += "libautojs6-node.so failed to load: ${bridgeLoad.error.toLoadErrorMessage().orEmpty()}"
        }
        if (probeLevel >= PROBE_LEVEL_LOAD_LIBNODE && nodeLoad.attempted && !nodeLoad.loaded) {
            errors += "libnode.so failed to load at probe level $probeLevel: ${nodeLoad.error.toLoadErrorMessage().orEmpty()}"
        }
        nativeError?.let {
            errors += "native embedded probe failed: ${it.message ?: it.javaClass.name}"
        }
        if (probeLevel in PROBE_LEVEL_LIBNODE_HANDLE..PROBE_LEVEL_DLSYM && bridgeLoad.loaded && nativeError == null && !libnodeHandleAvailable) {
            errors += "libnode.so handle is unavailable: ${libnodeHandleError.orEmpty()}"
        }
        if (probeLevel == PROBE_LEVEL_DLSYM && bridgeLoad.loaded && nativeError == null && !nodeStartFound) {
            errors += "node::Start(int,char**) symbol is missing."
        }
        val missingSymbols = symbolProbes.filterNot { it.found }
        if (probeLevel == PROBE_LEVEL_DLSYM && bridgeLoad.loaded && nativeError == null && missingSymbols.isNotEmpty()) {
            errors += "missing embedded Node.js symbols: ${missingSymbols.joinToString { it.description }}"
        }
        if (uvLoopInitProbe.status == "failed") {
            errors += "uv_loop_init probe failed: ${uvLoopInitProbe.detail.orEmpty()}"
        }
        if (initializeProbe.status == "failed") {
            errors += "InitializeOncePerProcess probe failed: ${initializeProbe.detail.orEmpty()}"
        }
        if (teardownProbe.status == "failed") {
            errors += "TearDownOncePerProcess probe failed: ${teardownProbe.detail.orEmpty()}"
        }
        if (platformCreateProbe.status == "failed") {
            errors += "MultiIsolatePlatform::Create probe failed: ${platformCreateProbe.detail.orEmpty()}"
        }
        if (v8InitializePlatformProbe.status == "failed") {
            errors += "V8::InitializePlatform probe failed: ${v8InitializePlatformProbe.detail.orEmpty()}"
        }
        if (v8InitializeProbe.status == "failed") {
            errors += "V8::Initialize probe failed: ${v8InitializeProbe.detail.orEmpty()}"
        }
        if (allocatorCreateProbe.status == "failed") {
            errors += "ArrayBufferAllocator::Create probe failed: ${allocatorCreateProbe.detail.orEmpty()}"
        }
        if (isolateCreateProbe.status == "failed") {
            errors += "NewIsolate probe failed: ${isolateCreateProbe.detail.orEmpty()}"
        }
        if (isolateDisposeProbe.status == "failed") {
            errors += "Isolate::Dispose probe failed: ${isolateDisposeProbe.detail.orEmpty()}"
        }
        if (uvLoopCloseProbe.status == "failed") {
            errors += "uv_loop_close probe failed: ${uvLoopCloseProbe.detail.orEmpty()}"
        }
        if (uvCloseProbe.status == "failed") {
            errors += "uv_close probe failed: ${uvCloseProbe.detail.orEmpty()}"
        }
        if (uvRunProbe.status == "failed") {
            errors += "uv_run cleanup probe failed: ${uvRunProbe.detail.orEmpty()}"
        }
        if (isolateDataCreateProbe.status == "failed") {
            errors += "CreateIsolateData probe failed: ${isolateDataCreateProbe.detail.orEmpty()}"
        }
        if (isolateDataFreeProbe.status == "failed") {
            errors += "FreeIsolateData probe failed: ${isolateDataFreeProbe.detail.orEmpty()}"
        }
        if (environmentCreateProbe.status == "failed") {
            errors += "CreateEnvironment probe failed: ${environmentCreateProbe.detail.orEmpty()}"
        }
        if (environmentFreeProbe.status == "failed") {
            errors += "FreeEnvironment probe failed: ${environmentFreeProbe.detail.orEmpty()}"
        }
        if (loadEnvironmentProbe.status == "failed") {
            errors += "LoadEnvironment probe failed: ${loadEnvironmentProbe.detail.orEmpty()}"
        }
        if (spinEventLoopProbe.status == "failed") {
            errors += "SpinEventLoop probe failed: ${spinEventLoopProbe.detail.orEmpty()}"
        }
        if (inlineJsProbe.status == "failed") {
            errors += "inline JavaScript probe failed: ${inlineJsProbe.detail.orEmpty()}"
        }
        if (processJsProbe.status == "failed") {
            errors += "process.version JavaScript probe failed: ${processJsProbe.detail.orEmpty()}"
        }
        if (consoleJsProbe.status == "failed") {
            errors += "console JavaScript probe failed: ${consoleJsProbe.detail.orEmpty()}"
        }
        if (probeLevel == PROBE_LEVEL_STDOUT_CAPTURE && stdoutCaptureProbe.status == "failed") {
            errors += "stdout capture probe failed: ${stdoutCaptureProbe.detail.orEmpty()}"
        }
        if (jsResultProbe.status == "failed") {
            errors += "JS result extraction probe failed: ${jsResultProbe.detail.orEmpty()}"
        }
        if (stdoutWriteProbe.status == "failed") {
            errors += "stdout write probe failed: ${stdoutWriteProbe.detail.orEmpty()}"
        }
        if (consoleDiagnosticsProbe.status == "failed") {
            errors += "console diagnostics probe failed: ${consoleDiagnosticsProbe.detail.orEmpty()}"
        }
        if (consoleStreamProbe.status == "failed") {
            errors += "console stream probe failed: ${consoleStreamProbe.detail.orEmpty()}"
        }
        if (consoleShapeProbe.status == "failed") {
            errors += "console shape probe failed: ${consoleShapeProbe.detail.orEmpty()}"
        }
        if (consoleReplaceProbe.status == "failed") {
            errors += "console replacement probe failed: ${consoleReplaceProbe.detail.orEmpty()}"
        }
        if (consoleFamilyProbe.status == "failed") {
            errors += "console family probe failed: ${consoleFamilyProbe.detail.orEmpty()}"
        }
        if (consoleFormatProbe.status == "failed") {
            errors += "console format probe failed: ${consoleFormatProbe.detail.orEmpty()}"
        }
        if (consoleRejectionProbe.status == "failed") {
            errors += "console rejection probe failed: ${consoleRejectionProbe.detail.orEmpty()}"
        }
        if (consoleUncaughtProbe.status == "failed") {
            errors += "console uncaught probe failed: ${consoleUncaughtProbe.detail.orEmpty()}"
        }
        if (uvDiagnosticsBeforeClose.status == "failed") {
            errors += "uv diagnostics before uv_loop_close failed: ${uvDiagnosticsBeforeClose.detail.orEmpty()}"
        }
        if (uvDiagnosticsAfterClose.status == "failed") {
            errors += "uv diagnostics after uv_loop_close failed: ${uvDiagnosticsAfterClose.detail.orEmpty()}"
        }
        if (uvDiagnosticsAfterUvClose.status == "failed") {
            errors += "uv diagnostics after uv_close failed: ${uvDiagnosticsAfterUvClose.detail.orEmpty()}"
        }
        if (uvDiagnosticsAfterLoopClose.status == "failed") {
            errors += "uv diagnostics after uv_loop_close failed: ${uvDiagnosticsAfterLoopClose.detail.orEmpty()}"
        }
        return errors.filter { it.isNotBlank() }.joinToString("\n").takeIf { it.isNotBlank() }
    }

    private fun failureProbeResult(
        context: Context,
        probeLevel: Int,
        processName: String,
        pid: Int,
        message: String,
    ): ProbeResult {
        return ProbeResult(
            expectedHeaderVersion = NODE_HEADER_VERSION,
            nodeVersion = "unknown",
            probeLevel = probeLevel.coerceIn(PROBE_LEVEL_MIN, PROBE_LEVEL_MAX),
            processName = processName,
            pid = pid,
            deviceSupportedAbis = Build.SUPPORTED_ABIS.toList(),
            currentAbi = Build.SUPPORTED_ABIS.firstOrNull().orEmpty(),
            nativeLibraryDir = context.applicationContext.applicationInfo.nativeLibraryDir,
            libnodeSha256 = nativeLibrarySha256(context, nativeLibrarySoFileName(NativeNodeRuntimeBridge.NODE_LIBRARY_NAME)),
            bridgeSha256 = nativeLibrarySha256(context, nativeLibrarySoFileName(NativeNodeRuntimeBridge.BRIDGE_LIBRARY_NAME)),
            libcxxLoaded = false,
            libcxxLoadError = null,
            libnodeLoaded = false,
            libnodeLoadError = null,
            bridgeLoaded = false,
            bridgeLoadError = null,
            libnodeHandleAvailable = false,
            libnodeHandleError = null,
            oneShotNodeStartSymbolFound = false,
            oneShotNodeStartSymbol = null,
            symbolProbes = emptyList(),
            uvLoopInit = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            uvLoopClose = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            initializeOncePerProcess = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            teardownOncePerProcess = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            platformCreate = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            v8InitializePlatform = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            v8Initialize = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            allocatorCreate = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            isolateCreate = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            isolateDispose = LifecycleProbe(status = "skipped", detail = "native probe not entered", durationMs = 0L),
            timings = ProbeTimings(
                loadMs = 0L,
                nativeLoadMs = 0L,
                symbolsMs = 0L,
                uvLoopInitMs = 0L,
                initializeMs = 0L,
                platformCreateMs = 0L,
                v8InitializePlatformMs = 0L,
                v8InitializeMs = 0L,
                allocatorCreateMs = 0L,
                isolateCreateMs = 0L,
                isolateDisposeMs = 0L,
                uvLoopCloseMs = 0L,
                teardownMs = 0L,
                nativeTotalMs = 0L,
                totalMs = 0L,
            ),
            lifecycleProbeRequested = false,
            lifecycleProbeBuildEnabled = false,
            isolateProbeRequested = false,
            isolateProbeBuildEnabled = false,
            uvLoopProbeRequested = false,
            uvLoopProbeBuildEnabled = false,
            v8ProbeRequested = false,
            v8ProbeBuildEnabled = false,
            errorMessage = message,
            cause = null,
        )
    }

    private fun String?.toBooleanValue(): Boolean = equals("true", ignoreCase = true)

    private fun String?.toLongValue(): Long = this?.toLongOrNull() ?: 0L

    private fun String?.toOptionalBoolean(): Boolean? = takeUnless { it.isNullOrBlank() }
        ?.equals("true", ignoreCase = true)

    private fun String?.toOptionalInt(): Int? = takeUnless { it.isNullOrBlank() }
        ?.toIntOrNull()

    private fun String?.toOptionalLong(): Long? = takeUnless { it.isNullOrBlank() }
        ?.toLongOrNull()

    private fun Throwable?.toLoadErrorMessage(): String? {
        return this?.let { "${it.javaClass.name}: ${it.message.orEmpty()}" }
    }

    private data class LibraryLoad(
        val name: String,
        val loaded: Boolean,
        val attempted: Boolean = true,
        val error: Throwable? = null,
    ) {
        companion object {
            fun skipped(name: String): LibraryLoad = LibraryLoad(name = name, loaded = false, attempted = false)
        }
    }

