    private data class DynamicStageField(
        val outputKey: String,
        val valueKind: DynamicStageValueKind,
    ) {
        fun value(nativeValues: Map<String, String>): Any = when (valueKind) {
            DynamicStageValueKind.Text -> nativeValues[outputKey].orEmpty()
            DynamicStageValueKind.Boolean -> nativeValues[outputKey].toBooleanValue()
            DynamicStageValueKind.LongOrZero -> nativeValues[outputKey]?.toLongOrNull() ?: 0L
            DynamicStageValueKind.SkippedIfMissing -> nativeValues[outputKey] ?: "skipped"
            DynamicStageValueKind.SkippedIfBlank -> nativeValues[outputKey].takeUnless { it.isNullOrBlank() } ?: "skipped"
        }
    }

    private enum class DynamicStageValueKind {
        Text,
        Boolean,
        LongOrZero,
        SkippedIfMissing,
        SkippedIfBlank,
    }

