            appendLine("  console_family.load_environment.result=${consoleFamilyLoadEnvironmentResult ?: "skipped"}")
            appendLine("  console_family.spin_event_loop.result=${consoleFamilySpinEventLoopResult ?: "skipped"}")
            appendLine("  console_family.result_text=${consoleFamilyResultText ?: ""}")
            appendLine("  console_family.stdout_captured=${consoleFamilyStdoutCaptured ?: ""}")
            appendLine("  console_family.stderr_captured=${consoleFamilyStderrCaptured ?: ""}")
            appendLine("  console_family.stdout_contains_version=$consoleFamilyStdoutContainsVersion")
            appendLine("  console_family.stderr_contains_version=$consoleFamilyStderrContainsVersion")
            appendLine("  console_family.stdout_fd=${consoleFamilyStdoutFd ?: ""}")
            appendLine("  console_family.stderr_fd=${consoleFamilyStderrFd ?: ""}")
            appendLine("  console_family.stdout_write_type=${consoleFamilyStdoutWriteType ?: ""}")
            appendLine("  console_family.stderr_write_type=${consoleFamilyStderrWriteType ?: ""}")
            appendLine("  consolefamily.requested=$consoleFamilyProbeRequested")
            appendLine("  consolefamily.build.enabled=$consoleFamilyProbeBuildEnabled")
            appendLine()
            appendUvDiagnosticsSection()
            appendUvCloseSection()
            appendUvRunSection()
            appendTimingsSection()
            appendErrorSection()
        }.trimEnd()

        private fun StringBuilder.appendProbeStagesSection() {
            if (stageEvents.isNotEmpty()) {
                appendLine()
                appendLine("Probe stages:")
                stageEvents.forEach { appendLine("  $it") }
            }
        }

