        private fun StringBuilder.appendUvDiagnosticsSection() {
            appendLine("Embedded uv diagnostics:")
            appendUvDiagnosticsSnapshot("before_close", uvDiagnosticsBeforeClose)
            appendUvDiagnosticsSnapshot("after_close", uvDiagnosticsAfterClose)
            appendUvDiagnosticsSnapshot("after_uv_close", uvDiagnosticsAfterUvClose)
            appendUvDiagnosticsSnapshot("after_loop_close", uvDiagnosticsAfterLoopClose)
            appendLine("  uvdiagnostics.requested=$uvDiagnosticsProbeRequested")
            appendLine("  uvdiagnostics.build.enabled=$uvDiagnosticsProbeBuildEnabled")
