        private fun StringBuilder.appendUvDiagnosticsSnapshot(
            label: String,
            snapshot: UvDiagnosticsSnapshot,
        ) {
            appendLine("  $label: ${snapshot.format()}")
            snapshot.formatTypeCounts().forEach { appendLine("    $it") }
            snapshot.formatHandles().forEach { appendLine("    $it") }
        }

