            appendLine("Embedded uv close:")
            appendLine("  uv_close: ${uvClose.format()}")
            appendLine("  uv.close.attempted=${uvCloseStats.attempted}")
            appendLine("  uv.close.succeeded=${uvCloseStats.succeeded}")
            appendLine("  uv.close.skipped=${uvCloseStats.skipped}")
            appendLine("  uv.close.failed=${uvCloseStats.failed}")
            appendLine("  uvclose.requested=$uvCloseProbeRequested")
            appendLine("  uvclose.build.enabled=$uvCloseProbeBuildEnabled")
            appendLine()
        }

        private fun StringBuilder.appendUvRunSection() {
            appendLine("Embedded uv run:")
            appendLine("  uv_run: ${uvRun.format()}")
            appendLine("  uv.run.mode=${uvRunStats.mode}")
            appendLine("  uv.run.max_iterations=${uvRunStats.maxIterations}")
            appendLine("  uv.run.completed_iterations=${uvRunStats.completedIterations}")
            uvRunStats.iterations.forEach {
                appendLine("  iteration.${it.index}: rc=${it.rc} handle.count=${it.handleCount} active=${it.active} closing=${it.closing}")
                it.diagnostics.formatTypeCounts().forEach { typeCount -> appendLine("    $typeCount") }
                it.diagnostics.formatHandles().forEach { handle -> appendLine("    $handle") }
            }
            appendLine("  uvrun.requested=$uvRunProbeRequested")
            appendLine("  uvrun.build.enabled=$uvRunProbeBuildEnabled")
            appendLine()
        }

