        private fun StringBuilder.appendErrorSection() {
            errorMessage?.let {
                appendLine()
                appendLine("Embedded probe error:")
                appendLine(it)
            }
        }

        private fun Boolean.toLoadStatus(error: String?): String {
            return if (this) "loaded" else "failed${error?.let { ": $it" }.orEmpty()}"
        }

        private fun Boolean.toFoundStatus(symbol: String?): String {
            return if (this) "found${symbol?.let { " ($it)" }.orEmpty()}" else "missing"
        }
    }

    data class SymbolProbe(
        val description: String,
        val found: Boolean,
        val resolvedSymbol: String?,
        val candidates: List<String>,
    )

    data class LifecycleProbe(
        val status: String,
        val detail: String?,
        val durationMs: Long,
    ) {
        fun format(): String {
            return status + detail?.takeIf { it.isNotBlank() }?.let { " ($it)" }.orEmpty()
        }
    }

    data class UvDiagnosticsSnapshot(
        val status: String,
        val detail: String?,
        val count: Int,
        val active: Int,
        val closing: Int,
        val typeCounts: Map<String, Int>,
        val handles: List<UvHandleDiagnostic>,
        val durationMs: Long,
    ) {
        fun format(): String {
            return buildString {
                append(status)
                append(" (count=$count, active=$active, closing=$closing")
                detail?.takeIf { it.isNotBlank() }?.let { append(", $it") }
                append(")")
            }
        }

        fun formatTypeCounts(): List<String> {
            return typeCounts.map { (type, count) -> "type.$type=$count" }
        }

        fun formatHandles(): List<String> {
            return handles.mapIndexed { index, handle ->
                "handle.$index type=${handle.type} active=${handle.active} closing=${handle.closing} address=${handle.address}"
            }
        }

        companion object {
            fun skipped(detail: String): UvDiagnosticsSnapshot = UvDiagnosticsSnapshot(
                status = "skipped",
                detail = detail,
                count = 0,
                active = 0,
                closing = 0,
                typeCounts = emptyMap(),
                handles = emptyList(),
                durationMs = 0L,
            )
        }
    }

    data class UvHandleDiagnostic(
        val address: String,
        val type: String,
        val active: Boolean,
        val closing: Boolean,
    )

    data class UvCloseStats(
        val attempted: Int = 0,
        val succeeded: Int = 0,
        val skipped: Int = 0,
        val failed: Int = 0,
    )

    data class UvRunIteration(
        val index: Int,
        val rc: Int,
        val handleCount: Int,
        val active: Int,
        val closing: Int,
        val diagnostics: UvDiagnosticsSnapshot,
    )

    data class UvRunStats(
        val mode: String = "UV_RUN_NOWAIT",
        val maxIterations: Int = 0,
        val completedIterations: Int = 0,
        val iterations: List<UvRunIteration> = emptyList(),
    )

    data class ProbeTimings(
        val loadMs: Long,
        val nativeLoadMs: Long,
        val symbolsMs: Long,
        val uvLoopInitMs: Long,
        val initializeMs: Long,
        val platformCreateMs: Long,
        val v8InitializePlatformMs: Long,
        val v8InitializeMs: Long,
        val allocatorCreateMs: Long,
        val isolateCreateMs: Long,
        val isolateDisposeMs: Long,
        val isolateDataCreateMs: Long = 0L,
        val isolateDataFreeMs: Long = 0L,
        val environmentCreateMs: Long = 0L,
        val environmentFreeMs: Long = 0L,
        val loadEnvironmentMs: Long = 0L,
        val spinEventLoopMs: Long = 0L,
        val uvLoopCloseMs: Long,
        val uvCloseMs: Long = 0L,
        val uvRunMs: Long = 0L,
        val uvDiagnosticsBeforeCloseMs: Long = 0L,
        val uvDiagnosticsAfterCloseMs: Long = 0L,
        val uvDiagnosticsAfterUvCloseMs: Long = 0L,
        val uvDiagnosticsAfterLoopCloseMs: Long = 0L,
        val teardownMs: Long,
        val nativeTotalMs: Long,
        val totalMs: Long,
    )
}
